    }).join('<span class="_eli3_team_sep">›</span>') + '<span class="_eli3_team_count">' + (BARE ? fmt(snap.elapsed * CLOCK) + " · " : "") + snap.revisions + (snap.revisions === 1 ? " revision" : " revisions") + "</span>";
    if (crumbs._html !== crumbHtml) { crumbs.innerHTML = crumbHtml; crumbs._html = crumbHtml; }
    if (snap.focus.label !== lastStatus) {
      lastStatus = snap.focus.label;
      stripNote.textContent = folded || lastStatus;
      if (RM || !painted) status.textContent = lastStatus;
      else { status.style.opacity = 0; setTimeout(function () { status.textContent = lastStatus; status.style.opacity = 1; }, TM.statusFade); }
    }
    var keep = {}, live = painted && !RM, cards = snap.cards;
    // compact: one card only — the newest finding — each new one replacing the last (the rest stay behind the seals)
    if (COMPACT && cards.length) { var top = cards[0], last = top.lines[top.lines.length - 1]; cards = [{ key: top.key + "#" + last.id, art: top.art, clause: top.clause, chips: top.chips, at: top.at, lines: [last] }]; }
    cards.forEach(function (c, i) {
      keep[c.key] = 1;
      var cd = cardEls[c.key];
      if (!cd) cd = cardEls[c.key] = cardEl(c, live);
      if (items.children[i] !== cd) items.insertBefore(cd, items.children[i] || null);
      c.lines.forEach(function (ln) {
        if (lineSeen[ln.id]) return;
        lineSeen[ln.id] = 1;
        cd._parts.lines.appendChild(lineEl(ln, live));
        if (live) { cd.classList.add("_ping"); setTimeout(function () { cd.classList.remove("_ping"); }, 60); }
      });
      var chipHtml = c.chips.map(function (ch) { return '<span class="_eli3_team_chip ' + (ch[1] ? "_" + ch[1] : "") + '">' + esc(ch[0]) + "</span>"; }).join("");
      if (cd._chipHtml !== chipHtml) { cd._parts.chips.innerHTML = chipHtml; cd._chipHtml = chipHtml; }
      cd._parts.ts.textContent = fmt(c.at * CLOCK);
      cd.classList.toggle("_top", i === 0);
      cd.classList.toggle("_old", i >= 2);
      cd.classList.toggle("_nolabel", i > 0 && cards[i - 1].art === c.art);
    });
    Object.keys(cardEls).forEach(function (k) { if (!keep[k]) { cardEls[k].remove(); delete cardEls[k]; } });
  }

  var folded = null;
  function paint(snap, now) {
    if (!laid) layout(snap.nodes);
    var dt = lastNow == null ? 0 : now - lastNow; lastNow = now; lastSnap = snap;
    clock.textContent = fmt(snap.elapsed * CLOCK);
    root.classList.toggle("_done", !!snap.done);
    drawChart(snap, dt, now);
    drawStrip(snap);
    drawStream(snap);
    if (picked) showFound();
    painted = true;
  }
  // yield to a step where the user is involved: the chart folds into the strip, progress is kept
  function fold(label) { folded = label || "Waiting for you"; stripNote.textContent = folded; root.classList.add("_folded"); }
  // the work resumes: the chart opens again with everyone who has worked still lit
  function unfold() { folded = null; stripNote.textContent = lastStatus || ""; root.classList.remove("_folded"); }
  // the calm end: strip on top, one result line, only what needs the user, everything else behind Details
  function finish(summary) {
    summary = summary || {};
    folded = null; root.classList.remove("_folded"); root.classList.add("_finished");
    var t = lastSnap ? fmt(lastSnap.elapsed * CLOCK) : "";
    result.textContent = (summary.headline || "Done") + (t ? " · " + t : "");
    needs.innerHTML = "";
    var list = summary.needsYou || [];
    needs.hidden = !list.length;
    if (list.length) {
      needs.appendChild(el("div", "_eli3_team_needshd", "Needs you"));
      list.forEach(function (it) {
        var b = el("button", "_eli3_team_need"); b.type = "button";
        b.appendChild(el("span", "_eli3_team_cl", it.clause || "")); b.appendChild(el("span", "_eli3_team_lt", it.text || ""));
        b.onclick = function () { if (typeof it.go === "function") it.go(); };
        needs.appendChild(b);
      });
    }
    details.appendChild(items);
    detailsBtn.hidden = summary.details === false;
    stripNote.textContent = "Tap an agent to see what it found";
  }
  function destroy() { if (root.parentNode) root.parentNode.removeChild(root); }
  return { paint: paint, fold: fold, unfold: unfold, finish: finish, destroy: destroy, root: root };
}

jsonTools.init:
function init(eli) {
  if (!eli || !eli.register) return;
  // engine.js and view.js load as the bundle's engine and view (kept on the bundle, not globals); a page or test that
  // loads the files as scripts has them as globals
  var bundle = (eli.tools && eli.tools._loaded && eli.tools._loaded.eli_team) || {};
  var Model = (bundle._eliEngineFns && bundle._eliEngineFns.eliTeamModel) || (typeof eliTeamModel === "function" ? eliTeamModel : null);
  var View = (bundle._eliViewFns && bundle._eliViewFns.eliTeamView) || (typeof eliTeamView === "function" ? eliTeamView : null);

  function open(mount, spec, speed) {
    spec = spec || {};
    if (!mount || !spec.team) return null;
    var tokens = eliTeamTokens(speed);
    if (!Model || !View) return null;
    var model = Model(spec.team, tokens);
    var view = View(mount, { eyebrow: spec.eyebrow || "", title: spec.title || "", tokens: tokens, clockScale: tokens.speed, bare: !!spec.bare, compact: !!spec.compact });
    var raf = 0, dead = false, idleSince = null, finished = false;
    function frame() {
      raf = 0;
      if (dead) return;
      if (!view.root.isConnected) { destroy(); return; }
      var now = Date.now(), snap = model.snapshot(now);
      view.paint(snap, now);
      // stop drawing once nothing moves: after sign-off, or while folded and idle
      var still = (snap.done || finished) && !snap.pulses.length && !snap.pop;
      if (still) { if (idleSince == null) idleSince = now; if (now - idleSince > 1500) return; } else idleSince = null;
      raf = requestAnimationFrame(frame);
    }
    function wake() { idleSince = null; if (!raf && !dead) raf = requestAnimationFrame(frame); }
    function destroy() { dead = true; if (raf) cancelAnimationFrame(raf); raf = 0; view.destroy(); }
    wake();
    return {
      event: function (ev) { var ok = model.event(ev); wake(); return ok; },
      fold: function (label) { view.fold(label); wake(); },
      unfold: function () { view.unfold(); wake(); },
      finish: function (summary) { finished = true; var now = Date.now(); view.paint(model.snapshot(now), now); view.finish(summary); wake(); },
      destroy: destroy,
    };
  }

  // the replay tile: the screen on a made-up run (later also a recorded Revise run's shape), no AI, no document
  function replay() {
    var out = eli.ui && eli.ui.claimOutput ? eli.ui.claimOutput() : null;
    if (!out) { if (typeof showToast === "function") showToast("The agent team replay couldn't find the panel.", "err"); return; }
    var RUNS = [{ id: "demo", label: "Demo run", get: eliTeamDemo }, { id: "recorded", label: "Recorded Revise run · coming soon", get: null }];
    var wrap = document.createElement("div"); wrap.className = "_eli3_team_demo";
    var bar = document.createElement("div"); bar.className = "_eli3_team_bar";
    var play = document.createElement("button"); play.type = "button"; play.className = "btn-platinum _eli3_team_btn"; play.textContent = "Play from start";
    var speeds = document.createElement("span"); speeds.className = "_eli3_team_seg";
    var pick = document.createElement("select"); pick.className = "_eli3_team_pick"; pick.setAttribute("aria-label", "Which run to replay");
    RUNS.forEach(function (r) { var o = document.createElement("option"); o.value = r.id; o.textContent = r.label; o.disabled = !r.get; pick.appendChild(o); });
    var speed = 1;
    [1, 2, 4].forEach(function (x) {
      var b = document.createElement("button"); b.type = "button"; b.className = "btn-platinum _eli3_team_btn" + (x === 1 ? " _on" : ""); b.textContent = x === 1 ? "Real time" : x + "×";
      b.onclick = function () { speed = x; [].forEach.call(speeds.children, function (c) { c.classList.toggle("_on", c === b); }); start(); };
      speeds.appendChild(b);
    });
    bar.appendChild(play); bar.appendChild(speeds); bar.appendChild(pick);
    var mount = document.createElement("div");
    wrap.appendChild(bar); wrap.appendChild(mount); out.appendChild(wrap);
    var ctl = null, timer = 0;
    function start() {
      if (ctl) ctl.destroy();
      if (timer) clearInterval(timer);
      var run = RUNS.filter(function (r) { return r.id === pick.value && r.get; })[0] || RUNS[0];
      var d = run.get(), base = Date.now(), i = 0;
      ctl = open(mount, d, speed);
      timer = setInterval(function () {
        if (!wrap.isConnected) { clearInterval(timer); ctl.destroy(); return; }
        var now = Date.now();
        while (i < d.events.length && base + d.events[i].at / speed <= now) {
          var e = d.events[i++];
          if (e.phase === "fold") ctl.fold(e.label);
          else if (e.phase === "unfold") ctl.unfold();
          else if (e.phase === "finish") ctl.finish(e.summary);
          else { var c = {}; for (var k in e) c[k] = e[k]; c.at = base + e.at / speed; ctl.event(c); }
        }
        if (i >= d.events.length) { clearInterval(timer); timer = 0; }
      }, 50);
    }
    play.onclick = start;
    pick.onchange = start;
    start();
  }

  eli.register({ tile: { app_eli_team: replay } });
  eli.register({ team: { open: function (mount, spec) { return open(mount, spec, 1); } } });
}

jsonTools.css:
/* tools/eli_team/style.css — agent-team activity screen. Colours and timings come from tokens.js (--et-* on the root). */
._eli3_team_demo { display: flex; flex-direction: column; gap: 8px; padding: 10px 0; background: #f5f7fa; min-height: 100%; }
._eli3_team_bar { display: flex; align-items: center; flex-wrap: wrap; gap: 6px; padding: 0 12px; }
._eli3_team_btn { border-radius: 0; padding: 6px 9px; font: 600 11px/1 "Segoe UI", system-ui, Arial, sans-serif; cursor: pointer; }
._eli3_team_btn._on { border-color: #c9a227; box-shadow: inset 0 -2px 0 #c9a227; }
._eli3_team_seg { display: inline-flex; gap: 2px; }
._eli3_team_pick { border-radius: 0; border: 1px solid #c3ccd8; background: #fff; font: 12px "Segoe UI", system-ui, Arial, sans-serif; padding: 5px 6px; min-width: 0; max-width: 100%; }

._eli3_team { background: var(--et-panel); color: var(--et-ink); font-family: "Segoe UI", system-ui, -apple-system, Arial, sans-serif; border: 1px solid var(--et-line); }
._eli3_team * { box-sizing: border-box; border-radius: 0; }
._eli3_team_stage, ._eli3_team_strip, ._eli3_team_cd, ._eli3_team_art, ._eli3_team_ln { grid-template-columns: minmax(0, 1fr); }
._eli3_team_stage > *, ._eli3_team_strip > *, ._eli3_team_cd > *, ._eli3_team_art > *, ._eli3_team_ln > * { min-width: 0; }
._eli3_team svg { max-width: 100%; }
._eli3_team_hd { background: var(--et-surface); border-bottom: 2px solid var(--et-gold); padding: 12px 14px 10px; }
._eli3_team_eyebrow { font: 700 9.5px/1 "Segoe UI", system-ui, Arial, sans-serif; letter-spacing: .17em; text-transform: uppercase; color: var(--et-gold-ink); }
._eli3_team_row { display: flex; justify-content: space-between; align-items: baseline; gap: 8px; margin-top: 8px; }
._eli3_team_ttl { font: 16px/1.15 Georgia, "Times New Roman", serif; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
._eli3_team_clock { font: 600 12.5px/1 Consolas, Menlo, monospace; font-variant-numeric: tabular-nums; }

/* the chart, and how it folds away for a step the user is part of */
._eli3_team_stage { padding: 8px 6px 4px; display: grid; grid-template-rows: 1fr; transition: grid-template-rows var(--et-fold) cubic-bezier(.2,.7,.2,1), opacity var(--et-fold) ease, padding var(--et-fold) ease; }
._eli3_team_chart { display: block; width: 100%; height: auto; min-height: 0; overflow: hidden; }
._eli3_team._folded ._eli3_team_stage, ._eli3_team._finished ._eli3_team_stage { grid-template-rows: 0fr; opacity: 0; padding-block: 0; }
._eli3_team_strip { display: grid; grid-template-rows: 0fr; opacity: 0; transition: grid-template-rows var(--et-fold) cubic-bezier(.2,.7,.2,1), opacity var(--et-fold) ease; background: var(--et-surface); border-bottom: 1px solid var(--et-line); }
._eli3_team_strip > * { min-height: 0; overflow: hidden; }
._eli3_team._folded ._eli3_team_strip, ._eli3_team._finished ._eli3_team_strip { grid-template-rows: auto auto auto; opacity: 1; padding: 10px 14px; }
._eli3_team_stripsvg { display: block; width: 100%; max-height: 34px; height: auto; }
._eli3_team_stripnote { font: italic 12px/1.3 Georgia, serif; color: var(--et-mute); margin-top: 6px; }
._eli3_team_found { margin-top: 8px; border-top: 1px solid var(--et-line); padding-top: 6px; }
._eli3_team_foundhd { font: 700 8.5px/1 "Segoe UI", system-ui, Arial, sans-serif; letter-spacing: .15em; text-transform: uppercase; color: var(--et-gold-ink); margin-bottom: 4px; }
._eli3_team_foundrow { display: flex; gap: 8px; align-items: baseline; padding: 3px 0; }
._eli3_team_foundrow ._eli3_team_cl { flex: none; font-size: 12.5px; }

/* the live stream */
._eli3_team_st { background: var(--et-surface); border-top: 1px solid var(--et-line); padding: 10px 14px 4px; height: 330px; overflow: hidden; position: relative; }
._eli3_team_st::after { content: ""; position: absolute; left: 0; right: 0; bottom: 0; height: 48px; background: linear-gradient(transparent, var(--et-surface)); pointer-events: none; }
._eli3_team._folded ._eli3_team_st, ._eli3_team._finished ._eli3_team_st { display: none; }
._eli3_team_crumbs { display: flex; align-items: center; gap: 6px; font-size: 11px; color: var(--et-mute); min-height: 20px; }
._eli3_team_crumbs b { color: var(--et-ink); font-weight: 600; }
._eli3_team_sep { color: var(--et-faint); }
._eli3_team_count { margin-left: auto; font-variant-numeric: tabular-nums; }
._eli3_team_status { font: 15px/1.3 Georgia, serif; margin-top: 6px; min-height: 20px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; transition: opacity .25s ease; }
._eli3_team_mono { display: inline-flex; align-items: center; justify-content: center; width: 22px; height: 22px; flex: none; background: var(--et-navy); color: var(--et-gold); border: 1px solid var(--et-gold); font: 700 8px/1 Georgia, serif; }
._eli3_team_mono._sm { width: 16px; height: 16px; font-size: 6.5px; }
._eli3_team_items { margin-top: 8px; display: flex; flex-direction: column; }

._eli3_team_cd { display: grid; grid-template-rows: 1fr; transition: grid-template-rows .5s cubic-bezier(.2,.7,.2,1); }
._eli3_team_cd._pre { grid-template-rows: 0fr; }
._eli3_team_in { overflow: hidden; min-height: 0; padding-bottom: 7px; transition: opacity .45s ease, transform .5s cubic-bezier(.2,.7,.2,1); }
._eli3_team_cd._pre ._eli3_team_in { opacity: 0; transform: translateY(-8px); }
._eli3_team_art { display: grid; grid-template-rows: 1fr; transition: grid-template-rows .4s ease, opacity .3s ease; }
._eli3_team_art > span { overflow: hidden; min-height: 0; font: 700 8.5px/1 "Segoe UI", system-ui, Arial, sans-serif; letter-spacing: .15em; text-transform: uppercase; color: var(--et-gold-ink); }
._eli3_team_art > span::after { content: ""; display: block; height: 5px; }
._eli3_team_cd._nolabel ._eli3_team_art { grid-template-rows: 0fr; opacity: 0; }
._eli3_team_card { border: 1px solid var(--et-line); background: var(--et-surface); padding: 8px 10px 9px; transition: border-color .6s ease, box-shadow .6s ease; }
._eli3_team_cd._top ._eli3_team_card { border-color: var(--et-gold); box-shadow: 0 6px 18px var(--et-shadow); }
._eli3_team_cd._ping ._eli3_team_card { box-shadow: 0 0 0 3px rgba(201,162,39,.28), 0 6px 18px var(--et-shadow); transition: none; }
._eli3_team_cardhd { display: flex; align-items: center; gap: 6px; }
._eli3_team_cl { font: 14px/1.25 Georgia, serif; flex: 1; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; color: var(--et-ink); }
._eli3_team_chips { display: flex; gap: 4px; }
._eli3_team_chip { font: 700 7.5px/1 "Segoe UI", system-ui, Arial, sans-serif; letter-spacing: .14em; text-transform: uppercase; color: var(--et-mute); border: 1px solid var(--et-line); padding: 3px 4px 2px; white-space: nowrap; }
._eli3_team_chip._lock { color: var(--et-gold-ink); border-color: var(--et-gold); }
._eli3_team_chip._rev { color: var(--et-gold-pale); background: var(--et-navy); border-color: var(--et-gold); }
._eli3_team_ts { font: 10px/1 Consolas, Menlo, monospace; color: var(--et-faint); font-variant-numeric: tabular-nums; }
._eli3_team_ln { display: grid; grid-template-rows: 1fr; transition: grid-template-rows .45s cubic-bezier(.2,.7,.2,1), opacity .4s ease; }
._eli3_team_ln._pre { grid-template-rows: 0fr; opacity: 0; }
._eli3_team_ln > div { overflow: hidden; min-height: 0; }
._eli3_team_lr { display: grid; grid-template-columns: 16px minmax(0, 1fr); column-gap: 8px; padding-top: 6px; }
._eli3_team_lr ._eli3_team_mono { margin-top: 1px; }
._eli3_team_lt { font-size: 11px; line-height: 1.4; color: var(--et-mute); min-width: 0; }
._eli3_team_lt b { color: var(--et-ink); font-weight: 600; }
._eli3_team_bd { font: 12.5px/1.5 Georgia, serif; color: var(--et-ink); margin-top: 3px; }
._eli3_team_bd del { color: var(--et-del); background-color: var(--et-prop-fill); text-decoration-thickness: 1.5px; }
._eli3_team_bd ins { color: var(--et-ins); background-color: var(--et-prop-fill); text-decoration-thickness: 1.5px; text-underline-offset: 2px; }
._eli3_team_cd._old ._eli3_team_ln:not(:last-child), ._eli3_team_cd._old ._eli3_team_bd { display: none; }
/* the redline is marked like a pen: the strike draws across, then the new words ink in and their underline draws */
._eli3_team_lr._fresh ._eli3_team_bd del { text-decoration: none; background: linear-gradient(currentColor, currentColor) no-repeat 0 60% / 0% 1.4px; -webkit-box-decoration-break: clone; box-decoration-break: clone; animation: _eli3_team_strike .7s .25s cubic-bezier(.45,0,.2,1) forwards; }
._eli3_team_lr._fresh ._eli3_team_bd ins { text-decoration: none; background: linear-gradient(currentColor, currentColor) no-repeat 0 100% / 0% 1px; -webkit-box-decoration-break: clone; box-decoration-break: clone; opacity: 0; animation: _eli3_team_ink .5s .95s ease forwards, _eli3_team_under .65s 1.05s cubic-bezier(.45,0,.2,1) forwards; }
@keyframes _eli3_team_strike { to { background-size: 100% 1.4px; } }
@keyframes _eli3_team_under { to { background-size: 100% 1px; } }
@keyframes _eli3_team_ink { to { opacity: 1; } }

/* the calm end: one result line, only what needs the user, the rest behind Details */
._eli3_team_end { display: none; padding: 12px 14px 14px; background: var(--et-surface); }
._eli3_team._finished ._eli3_team_end { display: block; }
._eli3_team_result { font: 17px/1.3 Georgia, serif; color: var(--et-ink); }
._eli3_team_needs { margin-top: 12px; border-top: 2px solid var(--et-gold); padding-top: 8px; }
._eli3_team_needshd { font: 700 9px/1 "Segoe UI", system-ui, Arial, sans-serif; letter-spacing: .16em; text-transform: uppercase; color: var(--et-gold-ink); margin-bottom: 6px; }
._eli3_team_need { display: flex; flex-direction: column; gap: 2px; width: 100%; text-align: left; background: var(--et-surface); border: 1px solid var(--et-line); padding: 8px 10px; margin-bottom: 6px; cursor: pointer; font: inherit; color: inherit; }
._eli3_team_need:hover, ._eli3_team_need:focus-visible { border-color: var(--et-gold); outline: none; }
._eli3_team_end > ._eli3_team_btn { margin-top: 10px; }
._eli3_team_details { display: none; margin-top: 10px; }
._eli3_team._showdetails ._eli3_team_details { display: block; }
._eli3_team_details ._eli3_team_cd._old ._eli3_team_ln, ._eli3_team_details ._eli3_team_cd._old ._eli3_team_bd { display: revert; }

/* bare: inside a host page (Ask ELI's agent mount) — no frame of its own, the stream flows in the page's one scroll */
._eli3_team._bare { border: 0; background: transparent; }
._eli3_team._bare ._eli3_team_st { height: auto; min-height: 120px; overflow: visible; padding-inline: 0; background: transparent; }
._eli3_team._bare ._eli3_team_st::after { display: none; }
._eli3_team._bare ._eli3_team_strip, ._eli3_team._bare ._eli3_team_end { background: transparent; padding-inline: 0; }
._eli3_team._bare ._eli3_team_stage { padding-inline: 0; }
/* compact: chart and one card fit the pane with no scrolling */
._eli3_team._compact ._eli3_team_st { min-height: 0; padding-top: 6px; }
._eli3_team._compact ._eli3_team_items { margin-top: 6px; }
._eli3_team._compact ._eli3_team_stage { padding-block: 4px 0; }

@media (prefers-reduced-motion: reduce) {
  ._eli3_team_cd, ._eli3_team_in, ._eli3_team_art, ._eli3_team_ln, ._eli3_team_card, ._eli3_team_status, ._eli3_team_stage, ._eli3_team_strip { transition: none; }
}
